// Real browser acceptance: explicit PLAYWRIGHT_MODULE, GITDASH_TEST_ORIGIN, GITDASH_TEST_OUTPUT.
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const {chromium} = require(process.env.PLAYWRIGHT_MODULE);
const origin=process.env.GITDASH_TEST_ORIGIN, output=process.env.GITDASH_TEST_OUTPUT;
assert.ok(origin && output);
(async()=>{
 const browser=await chromium.launch({headless:true});
 const ctx=await browser.newContext({viewport:{width:1440,height:1000},timezoneId:'Asia/Tokyo',permissions:['clipboard-read','clipboard-write']});
 const page=await ctx.newPage();page.setDefaultTimeout(15000);
 const errors=[],passed=[];page.on('pageerror',e=>errors.push(e.message));
 const clipboard=()=>page.evaluate(()=>navigator.clipboard.readText());
 const projectUrl=tab=>`${origin}/project?path=%2Fhome%2Fsolution2024%2Fgit-manager&tab=${tab}&range=current`;
 const download=async(name)=>{const pending=page.waitForEvent('download');await page.getByRole('button',{name,exact:true}).click();return fs.readFile(await(await pending).path(),'utf8');};
 const capture=async(name)=>{await page.screenshot({path:`${output}/${name}.png`});await page.setViewportSize({width:390,height:844});await page.screenshot({path:`${output}/${name}-mobile.png`});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),`${name} mobile overflow`);await page.setViewportSize({width:1440,height:1000});};
 await fs.mkdir(output,{recursive:true});
 try {
  await page.goto(projectUrl('activity'));await page.locator('.activity-list li').first().waitFor();
  const sourceBounds=await page.locator('.activity-list li').first().evaluate(row=>{const a=row.querySelector('.activity-source').getBoundingClientRect(), b=row.querySelector('.activity-content').getBoundingClientRect();return {right:a.right,left:b.left};});assert.ok(sourceBounds.right<=sourceBounds.left,'source/subject overlap');
  assert.ok(await page.locator('.activity-source').first().evaluate(el=>el.scrollWidth<=el.clientWidth+1),'source text overflow');
  const snapshot=await (await page.request.get(`${origin}/api/project?path=%2Fhome%2Fsolution2024%2Fgit-manager&range=current`)).json();
  const target=snapshot.events.filter(e=>e.type==='commit'&&e.lane_names.includes('main')).sort((a,b)=>Date.parse(b.occurred_at)-Date.parse(a.occurred_at))[0];
  const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(target.occurred_at));
  await page.getByLabel('作成者で完全一致の絞り込み').selectOption({label:target.author});
  await page.getByLabel('関連ブランチで完全一致の絞り込み').selectOption({label:'main'});
  await page.getByLabel('アクティビティの開始日').fill(day);await page.getByLabel('アクティビティの終了日').fill(day);
  await page.getByRole('searchbox',{name:'アクティビティを検索',exact:true}).fill(target.subject);
  await page.waitForFunction(()=>document.querySelectorAll('.activity-list li').length===1);
  assert.ok((await page.locator('.activity-list').innerText()).includes(target.commit_hash.slice(0,8)));
  await page.getByRole('button',{name:/一致する1件のアクティビティをMarkdownでコピー/}).click();assert.ok((await clipboard()).includes(target.commit_hash.slice(0,8)));
  const activityCsv=await download('一致するイベントをCSV保存');assert.ok(activityCsv.includes(target.commit_hash.slice(0,8))&&activityCsv.includes('"author"'));
  await capture('activity');
  await page.getByLabel('アクティビティの開始日').fill('2099-12-31');assert.ok((await page.locator('#activity-date-error').innerText()).includes('開始日は終了日以前'));assert.equal(await page.locator('.activity-list li').count(),0);
  await page.getByRole('button',{name:'一致するイベントをCSV保存',exact:true}).isDisabled().then(assert.ok);
  await page.locator('.empty-activity').getByRole('button',{name:'絞り込みを解除'}).click();await page.locator('.activity-list li').first().waitFor();
  const allCsv=await download('一致するイベントをCSV保存');assert.ok(allCsv.split('\r\n').length>102,'export includes records beyond first page');
  passed.push('Activity exact author/branch, inclusive local day, invalid range, complete Markdown/CSV export, source overlap fix');
  await page.goto(projectUrl('lanes'));await page.locator('#project-lane-results tr').first().waitFor();
  await page.getByLabel('最終コミット作成者で絞り込み').selectOption({label:'FujiwaraDaiki-NSE'});
  await page.getByRole('searchbox',{name:'作業レーンを検索',exact:true}).fill('/home/solution2024/git-manager');
  const sync=page.getByRole('group',{name:'upstream の同期状態で絞り込み'});await sync.getByRole('button',{name:/同期済み/}).click();
  assert.ok(await page.locator('#project-lane-results tr').count()>0);
  const lanesCsv=await download('一致するレーンをCSV保存');assert.ok(lanesCsv.includes('"synced"')&&lanesCsv.includes('"upstream_ahead"'));
  await page.locator('.lane-explorer-actions').getByRole('button',{name:/コピー/}).click();assert.ok((await clipboard()).includes('作業レーン引き継ぎ'));
  await capture('lanes');
  passed.push('Lane exact latest author, authoritative upstream filter, filtered CSV and Markdown handoff');
  await sync.getByRole('button',{name:/^すべて/}).click();
  const mainRow=page.locator('#project-lane-results tr').filter({has:page.locator('.lane-name-button strong').filter({hasText:/^main$/})});
  await mainRow.getByRole('button',{name:'Git詳細',exact:true}).click();
  const status=page.locator('.status-pane');await status.locator('.status-file-row').first().waitFor();
  await page.getByLabel('変更ファイルをディレクトリで絞り込み').selectOption({label:'frontend/app'});
  await page.getByLabel('変更ファイルを拡張子で絞り込み').selectOption({label:'.tsx'});
  assert.ok(await status.locator('.status-file-row').count()>=1);
  const paths=await status.locator('.status-file-path').allTextContents();
  await page.getByRole('button',{name:'パス順を降順に変更',exact:true}).click();
  assert.deepEqual(await status.locator('.status-file-path').allTextContents(),paths.toReversed());
  const statusDownload=page.waitForEvent('download');await status.getByRole('button',{name:/表示中の.*件をCSVで保存/}).click();
  const statusCsv=await fs.readFile(await(await statusDownload).path(),'utf8');assert.ok(statusCsv.includes('frontend/app/project-control.tsx'));
  await status.getByRole('button',{name:'未ステージの差分コマンドをコピー',exact:true}).click();assert.ok((await clipboard()).includes(':(literal)frontend/app/project-control.tsx'));
  await capture('status');
  passed.push('Real changed files directory/extension, ascending and descending order, filtered CSV and literal read-only diff command');
  // Browser-only SSE fixture covers states that must not be created in the user's repository.
  await page.route('**/api/stream',route=>route.fulfill({status:200,contentType:'text/event-stream',body:'event: snapshot\ndata: '+JSON.stringify([{path:'/home/solution2024/git-manager',name:'git-manager',common_dir:'/home/solution2024/git-manager/.git',is_worktree:false,worktree_state:'ok',branch:'main',entries:[{xy:'MM',path:'src/a [glob].ts'},{xy:'M.',path:'src/z.ts'},{xy:'??',path:'.env'},{xy:'UU',path:'conflict.ts'},{xy:'R.',path:'renamed.ts'},{xy:'.M',path:'=formula.txt'}]}])+'\n\n'}));
  await page.goto(projectUrl('lanes'));await page.locator('#project-lane-results tr').first().waitFor();
  await page.getByRole('searchbox',{name:'作業レーンを検索',exact:true}).fill('/home/solution2024/git-manager');
  await mainRow.getByRole('button',{name:'Git詳細',exact:true}).click();await status.locator('.status-file-row').first().waitFor();
  assert.equal(await status.locator('.status-file-row').count(),6);
  const fixtureAscending=await status.locator('.status-file-path').allTextContents();
  await page.getByRole('button',{name:'パス順を降順に変更',exact:true}).click();
  assert.deepEqual(await status.locator('.status-file-path').allTextContents(),fixtureAscending.toReversed());
  await page.getByLabel('変更ファイルをディレクトリで絞り込み').selectOption({label:'ルート'});
  await page.getByLabel('変更ファイルを拡張子で絞り込み').selectOption({label:'拡張子なし'});
  assert.deepEqual(await status.locator('.status-file-path').allTextContents(),['.env']);
  await status.locator('.status-file-tools-summary').getByRole('button',{name:'絞り込みを解除',exact:true}).click();
  await status.getByRole('button',{name:'ステージ済みの差分コマンドをコピー',exact:true}).click();
  const staged=await clipboard();assert.ok(staged.includes('--cached')&&staged.includes(':(literal)src/a [glob].ts'));assert.ok(!staged.includes('conflict.ts')&&!staged.includes('renamed.ts')&&!staged.includes('.env'));
  await status.getByRole('button',{name:'未ステージの差分コマンドをコピー',exact:true}).click();const unstaged=await clipboard();assert.ok(unstaged.includes(':(literal)src/a [glob].ts')&&unstaged.includes(':(literal)=formula.txt'));assert.ok(!unstaged.includes('src/z.ts'));
  const fixtureDownload=page.waitForEvent('download');await status.getByRole('button',{name:/表示中の.*件をCSVで保存/}).click();const fixtureCsv=await fs.readFile(await(await fixtureDownload).path(),'utf8');assert.ok(fixtureCsv.includes("'=formula.txt"));
  await page.getByRole('combobox',{name:'表示テーマ'}).count().then(async count=>{if(count) await page.getByRole('combobox',{name:'表示テーマ'}).selectOption('dark');});
  await capture('status-fixture');
  passed.push('Browser SSE fixture: root/dotfile, MM independently staged/unstaged, untracked/conflict/rename exclusions, CSV formula neutralization');
  assert.deepEqual(errors,[]);await fs.writeFile(`${output}/result.json`,JSON.stringify({origin,passed,errors},null,2));console.log({passed,errors});
 }catch(e){await page.screenshot({path:`${output}/failure.png`});console.error(e);console.error((await page.locator('body').innerText()).slice(-2000));process.exitCode=1;}
 finally{await browser.close();}
})();
